; Isolated live P3DM visual probe for Sather Tower / the Campanile.
;
; The canonical landmark corpus is regenerated by the build script. This
; fixture copies CAMPANIL.AGN and SOLID64.RG2 under 8.3 names, publishes the
; component into one stable slot, and places it at a local origin for an
; oblique recognition view. The mesh and exact uniform scale are unchanged.

mos_getkey: equ 00h
mos_load: equ 01h
mos_sysvars: equ 08h
sysvar_time: equ 00h
p3dm_mirror_z_on_load: equ 0
    MACRO MOSCALL function
        ld a,function
        rst.lil 08h
    ENDMACRO

    .assume adl=1
    .org 040000h
    jp start
    .align 64
    .db "MOS",0,1

start:
    push af
    push bc
    push de
    push ix
    push iy
    call main
    pop iy
    pop ix
    pop de
    pop bc
    pop af
    ld hl,0
    ret

    include "../../berkeley-flight-triangular-dither/src/vdu_pingo.inc"
    include "../../berkeley-flight-triangular-dither/src/agon/3d.inc"
    include "../../berkeley-flight-triangular-dither/src/agon/3d_sincos_table.inc"
    include "../../p3dm-loader-probe/src/p3dm-loader.inc"
    include "generated/campanile-probe.inc"

main:
    ld hl,title
    call printString

; Landmark selectors address a raw 8x8 native palette. There is deliberately
; no terrain pattern library, facade bitmap, or dither path in this fixture.
    ld bc,8
    ld de,8
    ld hl,landmark_bmid
    ld ix,64
    ld iy,landmark_palette_file
    ld a,1
    call vdu_load_img
    CTB2 tgtbmid,viewport_width,viewport_height
    CCS sid,viewport_width,viewport_height

; Establish a complete but inactive stable target before opening the AGNB.
; Any I/O, structure, policy, count, index, or CRC failure leaves it unchanged
; and emits no command 50.
    SV sid,probe_mesh_id,placeholder_vertices,placeholder_vertices_n
    SMVI sid,probe_mesh_id,placeholder_indices,placeholder_indices_n
    STC sid,probe_mesh_id,placeholder_uvs,placeholder_uvs_n
    STCI sid,probe_mesh_id,placeholder_uv_indices,placeholder_indices_n
    ld hl,probe_mesh_id
    ld a,pingo_shading_flat_palette
    call pingo_set_mesh_shading_mode
    ld hl,probe_mesh_id
    ld a,pingo_mesh_illumination_scene
    call pingo_set_mesh_illumination_mode
    CO sid,probe_object_id,probe_mesh_id,landmark_bmid
    ld hl,probe_object_id
    xor a
    call pingo_set_object_active

; A high oblique key light plus a restrained ambient floor keeps the warm
; stone, shadow stone, dark belfry and clock faces distinct.
    ld bc,-16384
    ld de,16384
    ld iy,-16384
    call pingo_set_light_direction
    ld a,72
    call pingo_set_ambient_light

    ld a,8+128
    call vdu_set_screen_mode
    xor a
    call vdu_set_scaling
    call vdu_clg
    call cursor_off
    call initialize_probe_camera
    jp c,@camera_failed

    call initialize_p3dm_request
    call p3dm_load_component
    jp nz,@failed
    call validate_published_descriptor
    jp nz,@failed

; Preserve the corpus scale exactly. Only translation changes: horizontal
; origin is local zero and generated Y places the decoded lowest vertex on the
; local ground plane within one translation quantum.
    SO sid,probe_object_id,campanile_scale_q8_8,campanile_scale_q8_8,campanile_scale_q8_8
    ld hl,probe_object_id
    ld bc,0
    ld de,campanile_local_translation_y
    ld iy,0
    call sodabs
    ld hl,probe_object_id
    ld a,1
    call pingo_set_object_active

    RENDBMP sid,tgtbmid
    call vdu_clg
    DISPBMP tgtbmid,0,0
    call vdu_flip
    ld hl,success_text
    call printString
@wait:
    MOSCALL mos_getkey
    cp 27
    jr nz,@wait
    jr @exit

@camera_failed:
    ld a,0EEh
@failed:
    push af
    ld hl,failure_text
    call printString
    pop af
    call print_hex_byte
    call printNewLine
    MOSCALL mos_getkey

@exit:
    xor a
    call vdu_set_screen_mode
    ld a,1
    call vdu_set_scaling
    call cursor_on
    ret

initialize_p3dm_request:
    ld hl,campanile_component_file
    ld (p3dm_filename_pointer),hl ; ADL24 OK: native 24-bit path pointer
    ld hl,probe_mesh_id
    ld a,l
    ld (p3dm_target_mesh_id+0),a
    ld a,h
    ld (p3dm_target_mesh_id+1),a
    ld a,3
    ld (p3dm_expected_layer),a
    xor a
    ld (p3dm_expected_lod),a
    ld (p3dm_expected_illumination),a
    ld a,pingo_shading_flat_palette
    ld (p3dm_expected_shading),a
    ld a,1
    ld (p3dm_expected_material_set),a
    ld hl,campanile_tile_x
    ld a,l
    ld (p3dm_expected_tile_x+0),a
    ld a,h
    ld (p3dm_expected_tile_x+1),a
    ld hl,campanile_tile_y
    ld a,l
    ld (p3dm_expected_tile_y+0),a
    ld a,h
    ld (p3dm_expected_tile_y+1),a
    ret

validate_published_descriptor:
    P3DM_LD_U16_HL p3dm_model_half_extent_m
    ld de,campanile_model_half_extent_m
    or a
    sbc hl,de
    jp nz,@bad
    P3DM_LD_U16_HL p3dm_vertex_count
    ld de,campanile_vertex_count
    or a
    sbc hl,de
    jp nz,@bad
    P3DM_LD_U16_HL p3dm_position_index_count
    ld de,campanile_position_index_count
    or a
    sbc hl,de
    jp nz,@bad
    xor a
    ret
@bad:
    ld a,p3dm_error_policy
    ld (p3dm_last_error),a
    or a
    ret

; Use the qualified integer camera solver rather than hand-authoring Euler
; words. Inputs are local Pingo translation counts (16 counts per metre).
initialize_probe_camera:
    ld ix,camera_state
    ld iy,camera_initial_position
    ld hl,sid
    call p3d_camera_init16
    ld iy,camera_target_position
    ld a,p3d_camera_roll_upright
    call p3d_camera_look_at_point16
    ret c
    call sync_camera_state
    or a
    ret

sync_camera_state:
    ld ix,camera_state
    bit 0,(ix+p3d_camera_dirty)
    jr z,@rotation
    ld c,(ix+p3d_camera_world_position+0)
    ld b,(ix+p3d_camera_world_position+1)
    ld e,(ix+p3d_camera_world_position+2)
    ld d,(ix+p3d_camera_world_position+3)
    ld l,(ix+p3d_camera_world_position+4)
    ld h,(ix+p3d_camera_world_position+5)
    push hl
    pop iy
    push ix
    call scdabs
    pop ix
    res 0,(ix+p3d_camera_dirty)
@rotation:
    bit 1,(ix+p3d_camera_dirty)
    ret z
    ld c,(ix+p3d_camera_pingo_rotation+0)
    ld b,(ix+p3d_camera_pingo_rotation+1)
    ld e,(ix+p3d_camera_pingo_rotation+2)
    ld d,(ix+p3d_camera_pingo_rotation+3)
    ld l,(ix+p3d_camera_pingo_rotation+4)
    ld h,(ix+p3d_camera_pingo_rotation+5)
    push hl
    pop iy
    push ix
    call scrabs
    pop ix
    res 1,(ix+p3d_camera_dirty)
    ret

print_hex_byte:
    push af
    rra
    rra
    rra
    rra
    and 0Fh
    call print_hex_nibble
    pop af
    and 0Fh
print_hex_nibble:
    add a,'0'
    cp '9'+1
    jr c,@emit
    add a,'A'-'9'-1
@emit:
    rst.lil 10h
    ret

title:
    db "Campanile P3DM probe: solid-flat native palette",13,10,0
success_text:
    db "CAMPANIL.AGN -> stable local landmark slot 1",13,10,0
failure_text:
    db "CAMPANILE FAIL 0x",0

sid: equ 1731
tgtbmid: equ 257
landmark_bmid: equ 256
viewport_width: equ 320
viewport_height: equ 240
p3dm_stage_buffer_id: equ 07400h
probe_mesh_id: equ 1
probe_object_id: equ 1

campanile_component_file: db "CAMPANIL.AGN",0
landmark_palette_file: db "SOLID64.RG2",0

; Camera (-144,72,+144) m looks at the 45 m tower center, showing two facades.
camera_initial_position: dw -2304,1152,2304
camera_target_position: dw 0,720,0
camera_state: ds p3d_camera_size

placeholder_vertices_n: equ 3
placeholder_vertices:
    dw -1,0,-1
    dw 1,0,-1
    dw 0,0,1
placeholder_indices_n: equ 3
placeholder_indices:
    dw 0,1,2
placeholder_uvs_n: equ 1
placeholder_uvs:
    dw 0,0
placeholder_uv_indices:
    dw 0,0,0

; MOS texture staging must remain the final application address.
filedata:
